"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SumMainDiagonal(matrix, N):
    diagonal_sum = 0
    for i in range(0, N):
        diagonal_sum = (diagonal_sum + matrix[i][i])
    return diagonal_sum

print(SumMainDiagonal([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 3))
print(SumMainDiagonal([[1, 2, 3, 4], [4, 5, 6, 7], [7, 8, 9, 10], [11, 12, 13, 14]], 4))
